#define NOMINMAX
#include <windows.h>
#include <dbghelp.h>
#include <tlhelp32.h>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>
#include <iostream>
namespace fs=std::filesystem;
static void dump(HANDLE process,DWORD pid,DWORD tid,const fs::path& root,const EXCEPTION_DEBUG_INFO& exception) {
 auto name=root/L"OpenFO_Diagnostics";fs::create_directories(name);std::ofstream log(name/"external_crash.txt",std::ios::app);log<<"code=0x"<<std::hex<<exception.ExceptionRecord.ExceptionCode<<" address="<<exception.ExceptionRecord.ExceptionAddress<<" first_chance="<<exception.dwFirstChance<<" thread="<<std::dec<<tid<<"\n";
 HANDLE thread=OpenThread(THREAD_GET_CONTEXT|THREAD_QUERY_INFORMATION,FALSE,tid);CONTEXT context{};context.ContextFlags=CONTEXT_FULL;if(thread&&GetThreadContext(thread,&context)){log<<std::hex<<"RIP="<<context.Rip<<" RSP="<<context.Rsp<<" RBP="<<context.Rbp<<"\n";std::vector<unsigned long long> stack(1024);SIZE_T read=0;if(ReadProcessMemory(process,reinterpret_cast<void*>(context.Rsp),stack.data(),stack.size()*8,&read))for(size_t i=0;i<read/8;i++)log<<"stack+0x"<<i*8<<" = 0x"<<stack[i]<<"\n";}if(thread)CloseHandle(thread);
 auto modules=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE|TH32CS_SNAPMODULE32,pid);if(modules!=INVALID_HANDLE_VALUE){MODULEENTRY32W m{};m.dwSize=sizeof m;if(Module32FirstW(modules,&m))do{log<<"module=0x"<<std::hex<<reinterpret_cast<uintptr_t>(m.modBaseAddr)<<" size=0x"<<m.modBaseSize<<" "<<fs::path(m.szExePath).u8string()<<"\n";}while(Module32NextW(modules,&m));CloseHandle(modules);}log.flush();
 wchar_t system[32768]{};auto n=GetSystemDirectoryW(system,32740);if(n&&n<32740){std::wcscat(system,L"\\dbghelp.dll");auto lib=LoadLibraryW(system);if(lib){using Write=BOOL(WINAPI*)(HANDLE,DWORD,HANDLE,MINIDUMP_TYPE,const PMINIDUMP_EXCEPTION_INFORMATION,const PMINIDUMP_USER_STREAM_INFORMATION,const PMINIDUMP_CALLBACK_INFORMATION);auto write=reinterpret_cast<Write>(GetProcAddress(lib,"MiniDumpWriteDump"));auto file=CreateFileW((name/L"external_crash.dmp").c_str(),GENERIC_WRITE,FILE_SHARE_READ,nullptr,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);if(write&&file!=INVALID_HANDLE_VALUE){EXCEPTION_RECORD record=exception.ExceptionRecord;EXCEPTION_POINTERS pointers{&record,&context};MINIDUMP_EXCEPTION_INFORMATION info{tid,&pointers,FALSE};BOOL ok=write(process,pid,file,MiniDumpNormal,context.Rip?&info:nullptr,nullptr,nullptr);log<<"dump_ok="<<ok<<" win32="<<GetLastError()<<"\n";}if(file!=INVALID_HANDLE_VALUE)CloseHandle(file);FreeLibrary(lib);}}
}
int main(int argc,char**argv){try{wchar_t exe[32768]{};GetModuleFileNameW(nullptr,exe,32768);auto root=fs::path(exe).parent_path();auto target=root/L"OpenFO.exe";std::wstring cmd=L"\""+target.wstring()+L"\"";for(int i=1;i<argc;++i){if(std::string(argv[i])=="--present-probe")cmd+=L" --present-probe";else throw std::runtime_error("Unsupported monitor argument");}STARTUPINFOW si{};si.cb=sizeof si;PROCESS_INFORMATION pi{};if(!CreateProcessW(target.c_str(),cmd.data(),nullptr,nullptr,FALSE,DEBUG_ONLY_THIS_PROCESS,nullptr,root.c_str(),&si,&pi))throw std::runtime_error("Cannot launch OpenFO Win32="+std::to_string(GetLastError()));CloseHandle(pi.hThread);bool captured=false,done=false;DWORD exit=1;while(!done){DEBUG_EVENT event{};if(!WaitForDebugEvent(&event,INFINITE))break;DWORD status=DBG_CONTINUE;switch(event.dwDebugEventCode){case CREATE_PROCESS_DEBUG_EVENT:if(event.u.CreateProcessInfo.hFile)CloseHandle(event.u.CreateProcessInfo.hFile);break;case CREATE_THREAD_DEBUG_EVENT:if(event.u.CreateThread.hThread)CloseHandle(event.u.CreateThread.hThread);break;case LOAD_DLL_DEBUG_EVENT:if(event.u.LoadDll.hFile)CloseHandle(event.u.LoadDll.hFile);break;case EXCEPTION_DEBUG_EVENT:{auto& e=event.u.Exception;if(e.ExceptionRecord.ExceptionCode!=EXCEPTION_BREAKPOINT){status=DBG_EXCEPTION_NOT_HANDLED;if((e.ExceptionRecord.ExceptionCode==EXCEPTION_STACK_OVERFLOW&&!captured)||!e.dwFirstChance){dump(pi.hProcess,pi.dwProcessId,event.dwThreadId,root,e);captured=true;}}break;}case EXIT_PROCESS_DEBUG_EVENT:exit=event.u.ExitProcess.dwExitCode;done=true;break;default:break;}ContinueDebugEvent(event.dwProcessId,event.dwThreadId,status);}CloseHandle(pi.hProcess);std::ofstream(root/"last_exit_code.txt")<<static_cast<int32_t>(exit)<<"\n";return int(exit);}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
